  'Source checks use HTTP GET. Unchanged automatic runs skip the agent. An optional JSON pointer watches only that value and ignores object key order. Manual tests always run. Quiet hours defer successful Bot reports. Failures and approvals stay visible. Usage limits can overrun when reports arrive late.':
    'Quellprüfungen verwenden HTTP GET. Bei unveränderten automatischen Läufen wird der Agent übersprungen. Ein optionaler JSON-Zeiger überwacht nur diesen Wert und ignoriert die Reihenfolge der Objektschlüssel. Manuelle Tests werden immer ausgeführt. Ruhige Stunden verzögern erfolgreiche Bot-Berichte. Fehler und Freigaben bleiben sichtbar. Wenn Berichte zu spät eintreffen, können die Nutzungsgrenzen überschritten werden.',
