  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Dieser Thread bleibt schreibgeschützt. Versuchen Sie den Umzug erneut oder brechen Sie ihn ab. „Abbrechen“ entsperrt den Thread erst, nachdem {value0} bestätigt hat, dass seine Kopie entfernt wurde. Wenn {value1} den Thread bereits empfangen hat, wird die Verschiebung stattdessen durch „Abbrechen“ beendet.',
