  'Automatic shell: {value0}. Default: -l (login shell).':
    'Automatische Shell: {value0}. Standard: -l (Login-Shell).',
  'Enable agent computer use on this computer':
    'Aktivieren Sie die Verwendung von Agent-Computern auf diesem Computer',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Gewährt beschreibbaren Agenten Zugriff auf den Desktop dieses Computers. Nur-Lese-Agenten sind ausgeschlossen. Der Benutzer und die Agenten teilen sich den Desktop- und App-Status.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Lassen Sie den Cua-Treiber leer, damit er im PATH dieses Computers oder im Standardinstallationsordner erkannt wird. Änderungen gelten für neue Agentenrunden.',
  '1. Install on this computer': '1. Auf diesem Computer installieren',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Führen Sie das offizielle Installationsprogramm auf dem Laufzeithost aus und aktualisieren Sie dann den Status. Es lädt CuaDriver herunter und installiert es; Es ist kein Cua-Konto erforderlich.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimale Linux-Systeme benötigen libxi6 und at-spi2-core. GNOME benötigt Cuas gebündelten WinRects-Helfer; siehe Installationsanleitung.',
  'Install and set up Cua Driver': 'Installieren und richten Sie den Cua-Treiber ein',
  'Detect / check Cua Driver': 'Cua-Treiber erkennen/überprüfen',
  '2. Permissions & desktop access': '2. Berechtigungen und Desktop-Zugriff',
  '3. Agent MCP, skills & hooks': '3. Agent MCP, Fähigkeiten und Haken',
  '4. Computer History (optional preview)': '4. Computerverlauf (optionale Vorschau)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Gewähren Sie CuaDriver macOS-Zugänglichkeit und Bildschirmaufzeichnung und akzeptieren Sie den Neustart. Testen Sie Apps für Desktop-Zugriffslisten, ohne sie zu ändern. Daemon-Steuerelemente wirken sich auf aktive Computernutzungssitzungen aus.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Speichern Sie den Computernutzungsschalter für automatisches dovo_cua MCP bei neuen beschreibbaren Runden. Es ist keine manuelle MCP-Registrierung erforderlich. Installieren Sie das optionale offizielle Skill-Pack. Installationslinks erkannten Agenten auf diesem Computer.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Opt-in, verschlüsselter, reiner Metadatenverlauf. Aktivieren kann den Daemon neu starten. Deaktivieren speichert aufgezeichnete Daten; Pause stoppt die Aufnahme vorübergehend. Nicht unterstützte Builds melden einen Fehler. Die Daten bleiben auf dem Laufzeithost; Hier können Sie den aktuellen Verlauf anzeigen, der bis zu 20 Ereignisse abruft.',
  'Delete recorded Computer History?': 'Aufgezeichneten Computerverlauf löschen?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Löschen Sie den gesamten aufgezeichneten Verlauf und seinen Verschlüsselungsschlüssel auf diesem Computer. Dies kann nicht rückgängig gemacht werden.',
