  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Der Computer muss die Weiterleitung in seinem Kopplungs-QR zulassen. Für eine reine Direktkopplung generieren Sie einen neuen Dovo-fähigen QR auf dem Computer und koppeln erneut.',
  'Scan pairing QR code': 'Scannen Sie den Pairing-QR-Code',
