  'Connect your phone': 'Schließen Sie Ihr Telefon an',
  'Scan the QR code in this app to connect over the internet. No VPN or local IP needed. You can also pair using a LAN / VPN address.':
    'Scanne den QR-Code in dieser App, um eine Internetverbindung herzustellen. Du brauchst weder VPN noch eine lokale IP-Adresse. Du kannst die Geräte auch über eine LAN-/VPN-Adresse koppeln.',
  'Internet connection': 'Internetverbindung',
  'WebRTC + STUN · end-to-end encrypted. No VPN or computer address needed. Keep Dovo open on the computer.':
    'WebRTC + STUN · Ende-zu-Ende-verschlüsselt. Kein VPN oder Computeradresse erforderlich. Halten Sie Dovo auf dem Computer geöffnet.',
  'Use a LAN / VPN address instead': 'Verwenden Sie stattdessen eine LAN-/VPN-Adresse',
  'Computer address': 'Computeradresse',
  'Wi-Fi, Tailscale and NetBird addresses all work. Include the port.':
    'Wi-Fi, Tailscale und NetBird-Adressen funktionieren alle. Geben Sie den Port an.',
