  'Keep this screen open and the computer online. If your computer asks, approve this phone there to finish.':
    'Lassen Sie diesen Bildschirm geöffnet und den Computer online. Wenn Ihr Computer Sie dazu auffordert, genehmigen Sie dieses Telefon dort, um den Vorgang abzuschließen.',
  'Cancel pairing': 'Kopplung abbrechen',
  Connect: 'Verbinden',
