  'Memory limit (MB)': 'Speicherlimit (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Führt den Agenten jeder neuen Unterhaltung, seine Befehle und seine Terminals in einem lokalen Docker- oder Podman-Container aus. Nur die Arbeitskopie und die Anmeldung des gewählten Agenten werden eingebunden. Laufende Unterhaltungen behalten ihre Einstellung.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Ohne Netzwerkzugriff erreicht der Agent seine Modell-API nicht, außer diese API läuft in der Sandbox. Paketinstallationen und Webanfragen schlagen ebenfalls fehl.',
  preparing: 'wird vorbereitet',
  stopped: 'gestoppt',
  'A thread can change it before its first message.':
    'Eine Unterhaltung kann dies vor ihrer ersten Nachricht ändern.',
  'Full network access. The agent can reach any address the host can.':
    'Voller Netzwerkzugriff. Der Agent kann jede Adresse erreichen, die der Host erreicht.',
  'Leave empty for no limit.': 'Leer lassen für kein Limit.',
  'Leave empty for the default of {value0} MB.':
    'Leer lassen für den Standardwert von {value0} MB.',
  'This thread runs in a Mise container sandbox.':
    'Diese Unterhaltung läuft in einer Mise-Container-Sandbox.',
  'The agent runs on this computer with your user account.':
    'Der Agent läuft auf diesem Computer mit Ihrem Benutzerkonto.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Der Agent, seine Befehle und seine Terminals laufen in einem Container. Nur diese Arbeitskopie und die Anmeldung des Agenten werden eingebunden.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Hält neue Arbeit, die ohne Ihre Nachricht läuft, an, sobald ihre geschätzten Kosten das Limit erreichen. Das gilt für Bot-Folgeschritte, Routinenschritte eines Bots, geplante Nachrichten und untergeordnete Agenten. Jeder Thread oder Bot zählt zusammen mit seinen untergeordneten Agenten. Eine Routine ohne Bot beginnt bei jedem Lauf eine neue Zählung. Legen Sie dafür ihre eigenen Grenzen unter Überwachung und Grenzen fest. Ihre nächste Nachricht oder Fortfahren setzt die Zählung zurück. Durchläufe ohne Preis halten Arbeit ebenfalls an. Ein laufender Durchlauf wird immer beendet.',
  'During your request: "{value0}"': 'Während deiner Anfrage: "{value0}"',
  'Git hooks do not run for commits in a sandboxed thread. The agent can change files that hooks run.':
    'Git-Hooks laufen bei Commits in einem Thread mit Sandbox nicht. Der Agent kann Dateien ändern, die Hooks ausführen.',
